<script setup>
import { computed, onMounted, ref } from 'vue';
import { brewApi } from '../api';
import { emptyIons, IONS, copy } from '../water-chemistry';
import JourneyDetailDialog from './JourneyDetailDialog.vue';
import WaterIonFields from './WaterIonFields.vue';
const data=ref({items:[],factories:[],can_manage:false}),factory=ref(''),loading=ref(false),saving=ref(false),error=ref(''),formError=ref(''),draft=ref(null);
const types={tap:'市政水',well:'地下水',ro:'RO 水',treated:'处理后酿造水',other:'其他水源'};
const rows=computed(()=>data.value.items.filter(s=>!factory.value||s.factory_id===factory.value));
const active=computed(()=>rows.value.filter(s=>s.active));
const date=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});
async function load(){loading.value=true;error.value='';try{data.value=await brewApi.getWaterSources();if(!factory.value&&data.value.factories.length===1)factory.value=data.value.factories[0].id;}catch(e){error.value=e.message;}finally{loading.value=false;}}
function edit(source){formError.value='';draft.value=source?copy(source):{factory_id:factory.value||data.value.factories[0]?.id||'',name:'',source_type:'treated',measured_on:date(),is_default:active.value.length===0,active:true,ions:emptyIons(),ph:'',alkalinity:'',report_reference:'',notes:''};}
async function save(){if(saving.value)return;saving.value=true;formError.value='';try{await brewApi.saveWaterSource(draft.value);draft.value=null;await load();}catch(e){formError.value=e.message;}finally{saving.value=false;}}
onMounted(load);
</script>
<template><section class="water-sources"><header class="water-source-heading"><div><small>酒厂基础水质</small><h2>水源水质</h2><p>维护实际酿造用水的检测数据，配方自动引用所属酒厂的默认水源。</p></div><div class="water-source-actions"><select v-model="factory" aria-label="筛选水源所属酒厂"><option value="">全部授权酒厂</option><option v-for="f in data.factories" :key="f.id" :value="f.id">{{ f.name }}</option></select><button class="btn btn-outline" :disabled="loading" @click="load">刷新</button><button v-if="data.can_manage" class="btn btn-primary" @click="edit()">＋ 新增水源</button></div></header><p v-if="error" class="master-error">{{ error }}</p><div v-if="loading" class="empty">正在加载水源…</div><div v-else-if="!rows.length" class="water-source-empty"><strong>还没有水源水质档案</strong><p>按检测报告填写六项离子和检测日期。RO 水也应填写实际检测值，未知项不会默认按零处理。</p><button v-if="data.can_manage" class="btn btn-primary" @click="edit()">建立第一个水源</button></div><div v-else class="water-source-grid"><article v-for="source in rows" :key="source.id" :class="{inactive:!source.active}"><header><div><small>{{ source.factory_name }} · {{ types[source.source_type] }}</small><h3>{{ source.name }}</h3></div><span v-if="!source.active" class="source-badge">已停用</span><span v-else-if="source.is_default" class="source-badge default">默认水源</span></header><p class="source-date">检测日期 {{ source.measured_on }}</p><dl class="source-ions"><div v-for="(label,key) in IONS" :key="key"><dt>{{ label }}</dt><dd>{{ source.ions[key] }} <small>mg/L</small></dd></div></dl><footer><div class="source-key-values"><span>pH <b>{{ source.ph??'未检测' }}</b></span><span>总碱度 <b>{{ source.alkalinity??'未检测' }}</b><small>mg/L · CaCO₃</small></span></div><button class="btn btn-sm btn-outline" @click="edit(source)">{{ data.can_manage?'查看 / 修改':'查看详情' }}</button></footer></article></div><JourneyDetailDialog v-if="draft" :title="draft.id?'水源档案详情':'新增水源档案'" subtitle="离子单位统一为 mg/L（稀水溶液中约等于 ppm）；总碱度以 CaCO₃ 计。" @close="!saving&&(draft=null)"><form id="water-source-edit" @submit.prevent="save"><fieldset :disabled="!data.can_manage || saving" class="water-source-form"><div class="source-basics"><label>所属酒厂<select v-model="draft.factory_id" :disabled="!!draft.id" required><option v-for="f in data.factories" :key="f.id" :value="f.id">{{ f.name }}</option></select></label><label>水源名称<input v-model.trim="draft.name" maxlength="100" required placeholder="例如：一号 RO 设备出水"></label><label>水源类型<select v-model="draft.source_type"><option v-for="(label,key) in types" :key="key" :value="key">{{ label }}</option></select></label><label>检测日期<input v-model="draft.measured_on" type="date" required :max="date()"></label></div><h4>原水离子检测值</h4><WaterIonFields :quality="draft" /><p class="source-hint">氯离子 Cl⁻ 与余氯不是同一指标；总碱度和总硬度也不能混填。碳酸氢根请按报告值填写。</p><label class="source-report">备注<textarea v-model.trim="draft.notes" rows="2" placeholder="例如：取样位置、预处理方式和检测条件"></textarea></label><div class="source-flags"><label><input v-model="draft.is_default" type="checkbox">设为本厂默认水源</label><label><input v-model="draft.active" type="checkbox">启用水源</label></div></fieldset><p v-if="formError" role="alert" class="master-error">{{ formError }}</p></form><template #footer><div class="water-source-modal-actions"><button class="btn btn-secondary" type="button" :disabled="saving" @click="draft=null">关闭</button><button v-if="data.can_manage" class="btn btn-primary" type="submit" form="water-source-edit" :disabled="saving">{{ saving?'保存中…':'保存水源档案' }}</button></div></template></JourneyDetailDialog></section></template>
<style scoped>
.water-sources{padding:8px 0}.water-source-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;margin:16px 0 24px}.water-source-heading small{font-size:11px;color:#d4b36b}.water-source-heading h2{font-size:24px;margin:8px 0 10px}.water-source-heading p,.source-hint{font-size:12px;line-height:1.8;color:var(--text-muted)}.water-source-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.water-source-actions select,.source-basics input,.source-basics select,.source-report input,.source-report textarea{box-sizing:border-box;min-height:42px;width:100%;padding:10px 12px;border:1px solid var(--border-default);border-radius:7px;background:var(--bg-input,#1b1c18);color:var(--text-primary);font:inherit}.water-source-actions select{width:auto}.water-source-overview{display:flex;align-items:center;gap:32px;border:1px solid var(--border-default);border-radius:10px;padding:20px 24px;margin-bottom:24px;background:#ffffff02}.water-source-overview span{display:block;font-size:11px;color:var(--text-muted)}.water-source-overview strong{display:block;font-size:28px;color:#e0bc70;margin-top:8px}.water-source-overview strong small{font-size:12px}.water-source-overview strong.scope{font-size:14px;white-space:nowrap}.water-source-overview p{margin-left:auto;max-width:360px;color:var(--text-muted);font-size:12px;line-height:1.9}.water-source-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.water-source-grid article{padding:22px;border:1px solid var(--border-default);border-radius:12px;background:#ffffff02}.water-source-grid article.inactive{opacity:.6}.water-source-grid article>header{display:flex;justify-content:space-between;gap:14px}.water-source-grid header small,.source-date{font-size:11px;color:var(--text-muted)}.water-source-grid h3{font-size:18px;margin:9px 0 12px}.source-badge{align-self:flex-start;border-radius:5px;padding:4px 8px;font-size:10px;color:var(--text-muted);background:#ffffff07}.source-badge.default{color:#e0bc70;background:#d4a85318}.source-ions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:20px 0}.source-ions dt{font-size:11px;color:var(--text-muted);margin-bottom:6px}.source-ions dd{font-size:20px;margin:0}.source-ions dd small{font-size:10px;color:var(--text-muted)}.water-source-grid article>footer{display:flex;justify-content:space-between;align-items:center;gap:12px;padding-top:16px;border-top:1px solid var(--border-default)}.water-source-grid footer>span{font-size:11px;color:var(--text-muted)}.water-source-empty{padding:48px 24px;text-align:center;border:1px dashed var(--border-default);border-radius:12px}.water-source-empty p{font-size:13px;line-height:1.9;color:var(--text-muted)}.water-source-form{border:0;padding:0;margin:0 0 20px}.source-basics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.source-basics label,.source-report{display:grid;gap:8px;color:var(--text-secondary);font-size:12px}.water-source-form h4{font-size:14px;margin:26px 0 16px}.source-report{margin-top:18px}.source-flags{display:flex;gap:24px;margin-top:20px;font-size:12px}@media(max-width:850px){.water-source-grid{grid-template-columns:1fr}.water-source-heading{flex-direction:column}.water-source-overview{flex-wrap:wrap;gap:20px}.water-source-overview p{margin:0}}@media(max-width:500px){.source-basics{grid-template-columns:1fr}.source-ions{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>

<style scoped>
.source-basics input,.source-basics select{height:44px;min-height:44px;max-height:44px;box-sizing:border-box;margin:0;line-height:22px;padding:10px 12px;font-size:14px}.source-basics label{align-content:start;grid-template-rows:auto 44px}
